UPDATE t_secre_disp_flow
SET content = #{content},
    stage = #{stage},
    status = #{status},
    last_action = #{lastAction},
    witness_one = #{witnessOne},
    witness_two = #{witnessTwo},
    pulp_no = #{pulpNo},
    update_by = #{updateBy},
    update_time = #{updateTime}
WHERE id = #{id}
  AND del_flag = 0
  AND status = #{expectStatus}
  AND stage = #{expectStage}
  AND CHAR_LENGTH(IFNULL(content, '')) = #{expectContentLen}
